mapper.update:
UPDATE tb_blog
SET liked = #{likeCount},
    favorites = #{favoriteCount}
WHERE id = #{blogId}

mapper.select:
SELECT b.*
FROM tb_blog b
WHERE b.status = 1
  AND b.user_id IN (
      SELECT f.follow_user_id FROM tb_follow f WHERE f.user_id = #{userId}
  )
  AND b.publish_time < #{maxTime}
ORDER BY b.publish_time DESC, b.id DESC
LIMIT #{offset}, #{size}
